/**
 * runbook-anchors.mjs — THE ONE OWNER of "which anchors does the app-developer runbook render".
 *
 * The runbook source is DeSciX/V2_docs/app-sdk/app-developer-runbook.md (Unkamon checkout),
 * built into the daita docs site by VitePress 1.6.4 with NO custom `markdown.anchor` /
 * `markdown.slugify` option (daita/site/.vitepress/config.mjs, generated by
 * DeSciX/scripts/build-docs-dist.mjs). VitePress therefore runs markdown-it-anchor over EVERY
 * heading level with:
 *   - the heading's text = the concatenated content of its `text` and `code_inline` tokens
 *     (backticks gone, code content kept);
 *   - VitePress's own slugify (vitepress/dist/node chunk, `const slugify = (str) => …`), copied
 *     verbatim below;
 *   - duplicate slugs suffixed `-1`, `-2`, … in document order (uniqueSlugStartIndex 1).
 *
 * Consumers: scripts/generate-cli-verbs.mjs (refuses to write a list carrying an anchor the
 * runbook does not render) and tests/cli-verbs-generated.test.js (the gate). Nothing else
 * derives a runbook anchor.
 *
 * FAILS LOUD instead of guessing: a heading carrying inline markup this extractor does not
 * render exactly as markdown-it would (emphasis, links, HTML, escapes, `{#id}` attrs) throws,
 * naming the line — extend the rule here, once, if the runbook ever needs one.
 */
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const CLI_ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..', '..');

/** The runbook source, located by the Unkamon checkout layout (DeSciX/DeSciX_Core beside DeSciX/V2_docs). */
export const RUNBOOK_SOURCE_PATH = path.resolve(CLI_ROOT, '..', '..', 'V2_docs', 'app-sdk', 'app-developer-runbook.md');

// VitePress 1.6.4 slugify, verbatim.
const rControl = /[\u0000-\u001f]/g;
const rSpecial = /[\s~`!@#$%^&*()\-_+=[\]{}|\;:"'“”‘’<>,.?/]+/g;
const rCombining = /[̀-ͯ]/g;

/** @param {string} str heading text (already stripped of markdown syntax) @returns {string} slug, no '#' */
export function vitepressSlug(str) {
  return str
    .normalize('NFKD')
    .replace(rCombining, '')
    .replace(rControl, '')
    .replace(rSpecial, '-')
    .replace(/-{2,}/g, '-')
    .replace(/^-+|-+$/g, '')
    .replace(/^(\d)/, '_$1')
    .toLowerCase();
}

const FENCE = /^ {0,3}(`{3,}|~{3,})/;
const ATX = /^ {0,3}(#{1,6})(?:[ \t]+(.*?))?(?:[ \t]+#+)?[ \t]*$/;
const UNSUPPORTED_INLINE = /[*_[\]<>\\{}`]/;
const SETEXT_UNDERLINE = /^ {0,3}(=+|-+)[ \t]*$/;

/** Heading text as markdown-it-anchor sees it: code spans keep their content, backticks go. */
function headingText(raw, lineNo) {
  let text = '';
  for (const part of raw.split(/(`+[^`]+`+)/)) {
    const code = part.match(/^(`+)([^`]+)\1$/);
    if (code) {
      const c = code[2];
      text += (c.startsWith(' ') && c.endsWith(' ') && c.trim()) ? c.slice(1, -1) : c;
      continue;
    }
    const bad = part.match(UNSUPPORTED_INLINE);
    if (bad) {
      throw new Error(
        `runbook-anchors: heading at line ${lineNo} ("${raw}") carries inline markup this extractor ` +
        `does not render ("${bad[0]}"). Extend scripts/lib/runbook-anchors.mjs to render it exactly ` +
        `as markdown-it does — never guess an anchor.`
      );
    }
    text += part;
  }
  return text.trim();
}

/**
 * Every anchor the runbook renders, in document order.
 * @param {string} markdown
 * @returns {{ anchor: string, level: number, text: string, line: number }[]} anchor carries the leading '#'
 */
export function runbookHeadingAnchors(markdown) {
  const out = [];
  const seen = new Set();
  let fence = null;
  const lines = markdown.split('\n');
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    const f = line.match(FENCE);
    if (fence) {
      if (f && f[1][0] === fence[0] && f[1].length >= fence.length && line.trim() === f[1]) fence = null;
      continue;
    }
    if (f) { fence = f[1]; continue; }
    if (SETEXT_UNDERLINE.test(line) && i > 0 && lines[i - 1].trim() !== '' && !ATX.test(lines[i - 1])
        && !FENCE.test(lines[i - 1]) && !/^\s*[|>]/.test(lines[i - 1]) && !/^\s*([-*+]|\d+\.)\s/.test(lines[i - 1])) {
      throw new Error(
        `runbook-anchors: line ${i + 1} underlines "${lines[i - 1]}" — a setext heading this extractor ` +
        `does not render. Use an ATX heading (## …) or extend scripts/lib/runbook-anchors.mjs.`
      );
    }
    const m = line.match(ATX);
    if (!m) continue;
    const text = headingText(m[2] || '', i + 1);
    const base = vitepressSlug(text);
    let slug = base;
    for (let n = 1; seen.has(slug); n++) slug = `${base}-${n}`;
    seen.add(slug);
    out.push({ anchor: `#${slug}`, level: m[1].length, text, line: i + 1 });
  }
  if (fence) throw new Error(`runbook-anchors: unterminated code fence (${fence}) — the heading scan cannot be trusted`);
  return out;
}

/**
 * The runbook's rendered anchors, read from the source. Throws when the source is absent — a
 * missing runbook is "could not measure", never "no anchors".
 * @param {string} [sourcePath]
 * @returns {Set<string>}
 */
export function readRunbookAnchors(sourcePath = RUNBOOK_SOURCE_PATH) {
  if (!fs.existsSync(sourcePath)) {
    throw new Error(
      `runbook-anchors: the runbook source is not at ${sourcePath}. The anchor gate reads ` +
      `DeSciX/V2_docs/app-sdk/app-developer-runbook.md from the Unkamon checkout layout ` +
      `(DeSciX/DeSciX_Core beside DeSciX/V2_docs); it cannot validate anchors without it.`
    );
  }
  const anchors = runbookHeadingAnchors(fs.readFileSync(sourcePath, 'utf8'));
  return new Set(anchors.map((h) => h.anchor));
}

/**
 * The declared anchors that the runbook does not render, as `"<verb>: <anchor>"` lines.
 * @param {{ verbPath: string, runbookAnchor: string|null }[]} verbs
 * @param {Set<string>} anchors
 */
export function unknownRunbookAnchors(verbs, anchors) {
  return verbs
    .filter((v) => v.runbookAnchor !== null && !anchors.has(v.runbookAnchor))
    .map((v) => `${v.verbPath}: ${v.runbookAnchor}`);
}
